const palette={'Patrimônio e recursos':'#006820','Democracia e eleições':'#0034D2','Saúde e pandemia':'#7a2bd6','Inteligência e instituições':'#B07A00','STF e controvérsias':'#0E7C7B','Violência e segurança':'#C2410C'};
