views.documents=['Documentos & processos','Leia as peças originais, entenda sua função e navegue pelas páginas selecionadas.','PDFs','Documentos'];
let state={view:'all',theme:'',group:'',year:0,person:'',status:'',query:''};
const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const formatDate=d=>d.length===7?d.split('-').reverse().join('/'):d.split('-').reverse().join('/');
function scopeRecords(){if(state.view==='documents')return cases;if(state.view==='speeches')return statements;return cases.filter(r=>state.view==='all'||(state.view==='flavio'&&r.people.includes('Flávio Bolsonaro'))||(state.view==='lula'&&r.cohort==='lula')||(state.view==='stf'&&r.stf)||(state.view==='allies'&&r.people.some(p=>allies.some(a=>a.name===p))));}
function filtered(){return scopeRecords().filter(r=>(!state.theme||r.theme===state.theme)&&(!state.group||r.group===state.group)&&(!state.year||r.year===state.year)&&(!state.person||r.people.includes(state.person))&&(!state.status||r.status===state.status)&&(!state.query||normalize([r.title,r.quote||'',r.medium||'',r.summary,r.outcome,r.theme,...r.people].join(' ')).includes(normalize(state.query))));}
function setView(view){state={view,theme:'',group:'',year:0,person:'',status:'',query:''};$('query').value='';if(history.replaceState)history.replaceState(null,'',view==='all'?location.pathname:'#'+view);refreshOptions();render();window.scrollTo({top:0});}
function refreshOptions(){const rec=scopeRecords();$('person').innerHTML='<option value="">Todas as pessoas</option>'+[...new Set(rec.flatMap(r=>r.people))].sort().map(p=>`<option>${esc(p)}</option>`).join('');$('status').innerHTML='<option value="">Todas as situações</option>'+[...new Set(rec.map(r=>r.status))].sort().map(s=>`<option>${esc(s)}</option>`).join('');}
function clearFilters(){state={...state,theme:'',group:'',year:0,person:'',status:'',query:''};$('query').value='';$('person').value='';$('status').value='';render();}
function render(){renderDocumentView();renderFeatured();const rows=filtered();const config=views[state.view];const speech=state.view==='speeches';const fullCorpus=state.view==='all'&&!state.theme&&!state.group&&!state.year&&!state.person&&!state.status&&!state.query;$('speech-coverage').hidden=!speech;$('unit-label').textContent='Episódios & casos';$('unit-note').textContent='Registros únicos';$('theme-title').textContent=speech?'Falas por tema':'Episódios por tema';$('status-title').textContent=speech?'Registro e repercussão':'Situação documentada';$('time-title').textContent=speech?'Ano da fala ou divulgação indicada':'Quando o episódio veio a público';$('results-heading').textContent=speech?'Declarações documentadas':'Explore os episódios';$('unit-foot').textContent=fullCorpus?'Os gráficos abaixo mostram episódios; os indicadores acima abrangem todo o acervo.':speech?'Unidade: declarações cadastradas · leia a data e o contexto na ficha':'Unidade: episódios cadastrados · não representa número de crimes';{const _p=String(config[0]).split('|');$('page-title').innerHTML=_p.length>1?esc(_p[0])+'<span class="hl">'+esc(_p[1])+'.</span>':esc(config[0])+'<span>.</span>';}$('page-description').textContent=config[1];$('breadcrumb').textContent=config[3].toUpperCase();$('scope').textContent=String(window.DOCUMENTS.length);$('scope-note').textContent='Peças originais';document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===state.view);b.setAttribute('aria-current',b.dataset.view===state.view?'page':'false');});$('ally-profiles').hidden=state.view!=='allies';$('total').textContent=String(cases.length);$('themes-total').textContent=String(statements.length);$('source-total').textContent=String(window.POLICIES_COUNT||0);$('themes-label').textContent='Falas documentadas';$('themes-note').textContent='Declarações';$('source-label').textContent='Políticas públicas';$('source-note').textContent='Desde 2003';
 $('active-filters').innerHTML=['theme','group','year','person','status','query'].filter(k=>state[k]).map(k=>`<button class="filter-chip" data-remove="${k}" aria-label="Remover filtro ${esc(state[k])}">${esc(state[k])} ×</button>`).join('');
 const themes=Object.keys(palette).filter(t=>scopeRecords().some(r=>r.theme===t)),counts=themes.map(t=>rows.filter(r=>r.theme===t).length),max=Math.max(1,...counts);
 $('theme-chart').innerHTML=themes.map((t,i)=>`<button class="bar-row" data-theme="${esc(t)}" aria-label="${esc(t)}: ${counts[i]} ${unit}. Filtrar" aria-pressed="${state.theme===t}" style="--bar:${palette[t]}"><span class="bar-name">${esc(t)}</span><span class="bar-track"><span class="bar-fill" style="width:${counts[i]/max*100}%"></span></span><span class="bar-number">${counts[i]}</span></button>`).join('');
 $('status-chart').innerHTML=Object.entries(groupColors).filter(([g])=>scopeRecords().some(r=>r.group===g)).map(([g,c])=>{const n=rows.filter(r=>r.group===g).length;return `<button class="status-row" data-group="${esc(g)}" aria-pressed="${state.group===g}" aria-label="${esc(g)}: ${n} ${unit}. Filtrar" style="--bar:${c}"><span class="status-dot"></span><span>${esc(g)}</span><b>${n}</b><small><i style="width:${n/Math.max(1,rows.length)*100}%"></i></small></button>`}).join('');
 const years=[...new Set(scopeRecords().map(r=>r.year))].sort();const yearMax=Math.max(1,...years.map(y=>rows.filter(r=>r.year===y).length));$('timeline').innerHTML=years.map(y=>{const n=rows.filter(r=>r.year===y).length;return `<button class="year" data-year="${y}" aria-pressed="${state.year===y}" aria-label="${y}: ${n} ${unit}. Filtrar"><b>${n||''}</b><i style="height:${n/yearMax*70}px"></i><span>${y}</span></button>`}).join('');
 renderPeople(rows,unit);$('result-count').textContent=`${rows.length} de ${scopeRecords().length} ${unit}`;$('cards').innerHTML=[...rows].sort((a,b)=>(b.eventDate||b.date).localeCompare(a.eventDate||a.date)).map(r=>`<article class="case-card" style="--case-color:${palette[r.theme]}"><div class="card-top"><span>${esc(r.theme.toUpperCase())}</span><span>${r.id} / ${r.year}</span></div><h3>${esc(r.title)}</h3><p class="people">${r.people.map(esc).join(' · ')}</p>${r.kind==='speech'?speechExcerpt(r):''}<p class="summary">${esc(r.summary)}</p><p class="record-date">Último marco: ${formatDate(r.date)}${r.reviewedAt?' · Dossiê revisado':''}</p><a class="record-link" href="${recordUrl(r)}">${r.dossier?'Dossiê completo':'Página permanente'} ↗</a><div class="card-bottom"><span class="badge">${esc(r.status)}</span><button class="card-open" data-case="${r.id}" aria-label="Abrir ficha: ${esc(r.title)}">Abrir ficha +</button></div></article>`).join('');$('empty').hidden=rows.length>0;
}
function openCase(id){const r=allRecords.find(x=>x.id===id);if(!r)return;if(r.kind==='speech'){openSpeech(r);return;}$('dialog-label').textContent=`${r.id} / ${r.theme.toUpperCase()}`;$('dialog-body').innerHTML=`<span class="badge">${esc(r.status)}</span><h2 id="dialog-title">${esc(r.title)}</h2>${permanentLink(r)}<p class="people">Pessoas com conduta descrita: ${r.people.map(esc).join(' · ')}</p><h3>O episódio</h3><p>${esc(r.summary)}</p><h3>O que a fonte mais recente registra</h3><p>${esc(r.outcome)}</p><h3>Resposta e contexto</h3><p>${esc(r.response)}</p>${caseDepth(r)}<h3>Fontes para conferir</h3><ul>${r.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)}</a></li>`).join('')}</ul><p class="detail-date">Último marco documentado: ${formatDate(r.date)} · Consulta editorial: 09/10/2026.<br>Não é uma certidão processual atualizada em tempo real.</p>`;$('detail').showModal();}
function openMethod(){const sources=[...new Map(allRecords.flatMap(r=>r.sources).map(s=>[s.url,s])).values()];$('dialog-label').textContent='FONTES & METODOLOGIA';$('dialog-body').innerHTML=`<h2 id="dialog-title">Como ler este acervo</h2><p>Os indicadores do topo, na visão geral sem filtros, somam 1.960 registros de formatos diferentes: 1.806 candidaturas no diretório eleitoral de 2026 (inclui 32 registros de segundo turno), 24 episódios, 26 falas, 26 cartões de ações e políticas, 9 documentos, 30 partidos registrados, 30 mudanças históricas e 9 referências partidárias. As nove referências partidárias incluem ligações a um mesmo caso histórico e não são nove episódios únicos. O catálogo de temas reúne 30 categorias presentes nas páginas de episódios, falas e políticas. O contador de links soma 327 ocorrências em 58 páginas HTML públicas; elas correspondem a 146 URLs externas únicas, com repetições quando a fonte é citada em mais de uma página. Estes totais foram conferidos em 10/10/2026; o feed automático de notícias, que muda periodicamente, não está incluído. Cinco fichas receberam revisão aprofundada nesta edição; as demais preservam a data de sua última fonte. Novos registros exigem apuração e atualização manual.</p><p><a href="/acervo-metrics.json" target="_blank" rel="noopener noreferrer">Abrir o detalhamento dos indicadores ↗</a></p><h3>Linha editorial crítica</h3><p>O acervo cobra responsabilidade de agentes públicos e distingue opinião editorial de fatos documentados. A crítica ao autoritarismo, ao uso privado da máquina pública e à opacidade institucional não autoriza omitir arquivamentos ou atribuir crimes sem fundamento. As análises das fichas são interpretações das fontes ali listadas.</p><h3>Documentos originais</h3><p>A biblioteca reúne cópias integrais e acessos oficiais. Página significa posição no arquivo PDF, que pode divergir da numeração impressa. O hash identifica os bytes da cópia recebida; não certifica a assinatura digital. Documentos extensos podem abrir na origem. Nem todas as fichas têm inteiro teor disponível.</p><h3>Falas na mídia</h3><p>A aba reúne figuras públicas: Jair, Flávio, Eduardo, Carlos, Michelle e Jair Renan Bolsonaro, além de nove aliados ou integrantes históricos do governo. Não abrange todos os familiares ou apoiadores. Aspas indicam um trecho literal curto; quando não há citação literal, a ficha identifica uma síntese editorial. A data distingue fala, gravação e divulgação quando as fontes permitem. O contexto completo pode ser conferido nos links. Declarações não são somadas aos processos nos gráficos das outras abas.</p><h3>O que os gráficos medem</h3><p>Cada barra conta episódios cadastrados, não crimes, vítimas, valores desviados ou grau de culpa. Processos relacionados podem se sobrepor. Um episódio com várias pessoas conta uma vez nos totais. No gráfico por pessoa, ele aparece em cada nome associado; as barras não devem ser somadas e não medem culpa. A cronologia usa o ano de divulgação do episódio adotado no acervo, não o ano de toda decisão posterior.</p><h3>Como os recortes funcionam</h3><p>Flávio reúne fichas que o mencionam como pessoa com conduta descrita. STF inclui processos que passaram pelo tribunal e controvérsias sobre seus ministros. Apoiadores reúne vínculos políticos históricos e atuação no governo, documentados em cada perfil. Fotografias de encontros não provam participação conjunta em qualquer ilícito.</p><h3>Situações não são equivalentes</h3><p>Investigação apura suspeitas. Indiciamento é uma conclusão policial. Uma denúncia pode ser rejeitada. Arquivamento encerra uma apuração no alcance da decisão. Condenações eleitorais e criminais são distintas. A categoria “Decisão condenatória” inclui ambas e também a condenação de Valdemar com indulto posterior; consulte sempre a situação exata da ficha.</p><h3>Datas e limites</h3><p>A data da ficha é a do último marco documentado nas fontes reunidas, que pode ser anterior à consulta editorial. A ausência de notícia posterior não comprova que um processo segue no mesmo estágio. A seleção prioriza documentos oficiais e jornalismo identificado. Não atribuímos crime por parentesco, amizade ou participação em fotografia.</p><h3>Fotografias</h3><p>Três imagens oficiais via Wikimedia Commons, licenciadas em CC BY 2.0, com crédito e link em cada perfil. Os enquadramentos na interface são recortes de exibição; não há montagem de encontros.</p><h3>Fontes das fichas de episódios e falas (${sources.length})</h3><ul>${sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)}</a></li>`).join('')}</ul>`;$('detail').showModal();}
function speechExcerpt(r){return `<div class="speech-date">${esc(r.dateBasis)} · ${formatDate(r.eventDate)}</div>${r.quote?`<blockquote>“${esc(r.quote)}”<cite>Trecho curto · ${esc(r.people[0])}</cite></blockquote>`:'<div class="paraphrase">Síntese editorial · não é citação literal</div>'}`;}
function openSpeech(r){$('dialog-label').textContent=`${r.id} / FALAS NA MÍDIA`;$('dialog-body').innerHTML=`<span class="badge">${esc(r.status)}</span><h2 id="dialog-title">${esc(r.title)}</h2>${permanentLink(r)}<p class="people">Autor: ${esc(r.people[0])}</p>${speechExcerpt(r)}<h3>Onde foi dito ou publicado</h3><p>${esc(r.medium)}</p>${r.affiliation?`<p class="affiliation">Vínculo documentado: ${esc(r.affiliation)}</p>`:''}<h3>Contexto da declaração</h3><p>${esc(r.summary)}</p><h3>Resposta e desdobramentos documentados</h3><p>${esc(r.response)}</p>${relatedDocuments(r)}<h3>Reportagem, vídeo ou documento</h3><ul>${r.sources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)}</a></li>`).join('')}</ul><p class="detail-date">Último marco desta ficha: ${formatDate(r.date)} · Consulta editorial: 09/10/2026.<br>Uma fala polêmica não equivale automaticamente a crime. O acervo não confirma desdobramentos posteriores aos documentados aqui.</p>`;$('detail').showModal();}
function renderSpeechPeople(){$('speech-people').innerHTML=[...new Set(statements.flatMap(r=>r.people))].map(p=>`<button data-speaker="${esc(p)}">${esc(p)} <span>${statements.filter(r=>r.people.includes(p)).length}</span></button>`).join('');}
function renderAllies(){$('ally-profiles').innerHTML=allies.map(a=>`<article class="ally-profile">${a.photo?`<img src="${a.photo}" alt="${esc(a.alt)}" loading="lazy">`:''}<div class="ally-content"><h3>${esc(a.name)}</h3><p>${esc(a.role)}</p><a href="${esc(a.url)}" target="_blank" rel="noopener noreferrer">Fonte do vínculo político</a>${a.photo?`<p class="photo-credit">${esc(a.credit)} · recorte de exibição<br><a href="${esc(a.origin)}" target="_blank" rel="noopener noreferrer">Foto original</a> · <a href="https://creativecommons.org/licenses/by/2.0/" target="_blank" rel="noopener noreferrer">CC BY 2.0</a></p>`:'<p class="photo-credit">Sem foto conjunta selecionada.</p>'}<button class="text-button" data-ally="${esc(a.name)}">Ver episódios (${cases.filter(r=>r.people.includes(a.name)).length})</button></div></article>`).join('');}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view)setView(b.dataset.view);if(b.dataset.theme){state.theme=state.theme===b.dataset.theme?'':b.dataset.theme;render();}if(b.dataset.group){state.group=state.group===b.dataset.group?'':b.dataset.group;render();}if(b.dataset.year){state.year=state.year===+b.dataset.year?0:+b.dataset.year;render();}if(b.dataset.remove){const key=b.dataset.remove;state[key]=key==='year'?0:'';if(['person','status','query'].includes(key))$(key).value='';render();}if(b.dataset.case)openCase(b.dataset.case);if(b.dataset.speaker){clearFilters();state.person=b.dataset.speaker;$('person').value=state.person;render();$('results-heading').scrollIntoView({behavior:'smooth',block:'start'});}if(b.dataset.ally){clearFilters();state.person=b.dataset.ally;$('person').value=state.person;render();$('results-heading').scrollIntoView({behavior:'smooth',block:'start'});}});
$('query').addEventListener('input',e=>{state.query=e.target.value;render()});['person','status'].forEach(k=>$(k).addEventListener('change',e=>{state[k]=e.target.value;render()}));['clear','empty-clear'].forEach(k=>$(k).addEventListener('click',clearFilters));['method','sources','footer-method'].forEach(k=>$(k).addEventListener('click',openMethod));$('close-dialog').addEventListener('click',()=>$('detail').close());$('detail').addEventListener('click',e=>{if(e.target===$('detail')){const r=$('detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('detail').close();}});document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();setView('all');window.scrollTo({top:0,behavior:'smooth'});});renderAllies();renderSpeechPeople();{const _h=location.hash.slice(1);if(Object.prototype.hasOwnProperty.call(views,_h))state.view=_h;}refreshOptions();render();
