if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 try{Promise.resolve(document.modelContext.registerTool({name:'filter_documented_cases',title:'Filtrar episódios documentados',description:'Seleciona a aba e um tema ou busca textual no acervo local. Atualiza os gráficos e as fichas visíveis; não modifica os dados.',inputSchema:{type:'object',properties:{view:{type:'string',enum:Object.keys(views).filter(v=>v!=='documents')},theme:{type:'string',enum:['',...Object.keys(palette)]},query:{type:'string',maxLength:200}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||typeof input!=='object'||(!Object.hasOwn(views,input.view)||input.view==='documents')||Object.keys(input).some(k=>!['view','theme','query'].includes(k))||(input.theme!==undefined&&input.theme!==''&&!Object.hasOwn(palette,input.theme))||(input.query!==undefined&&(typeof input.query!=='string'||input.query.length>200)))throw new Error('Filtro inválido.');setView(input.view);state.theme=input.theme||'';state.query=input.query||'';$('query').value=state.query;render();return {count:filtered().length,ids:filtered().map(r=>r.id),view:state.view};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}

function documentCard(d){return `<article class="document-card"><div class="card-top"><span>${esc(d.kind.toUpperCase())}</span><span>${d.pages?d.pages.toLocaleString('pt-BR')+' PÁGINAS':'ACESSO OFICIAL'}</span></div><h3>${esc(d.title)}</h3><p class="people">${esc(d.issuer)} · ${esc(d.process)}</p><p>${esc(d.summary)}</p><p class="doc-limit"><strong>Alcance:</strong> ${esc(d.limits)}</p><div class="doc-actions"><a class="source-btn" href="${esc(d.path)}" target="_blank" rel="noopener noreferrer">${d.local?'Abrir PDF disponível':'Abrir PDF na origem'} ↗</a>${d.local?`<a href="${esc(d.path)}" download>Baixar cópia</a>`:''}<a href="${esc(d.originUrl)}" target="_blank" rel="noopener noreferrer">Fonte oficial / publicação</a></div>${d.guide.length?`<div class="reading-guide"><strong>Roteiro de leitura · página do PDF</strong>${d.guide.map(g=>`<a href="${esc(d.path)}#page=${g.page}" target="_blank" rel="noopener noreferrer"><b>${g.page}</b><span>${esc(g.label)} ↗</span></a>`).join('')}</div>`:''}<details><summary>Proveniência e integridade</summary><p>${esc(d.dateLabel)}: ${formatDate(d.date)}. Consulta: 09/10/2026.</p><p>${d.bytes?(d.bytes/1048576).toFixed(2)+' MB · PDF aberto e identificação conferida.':'Download automatizado indisponível; consulte o portal.'} ${d.projectPath?'Cópia integral na pasta '+esc(d.projectPath)+' do projeto.':''}</p>${d.sha256?`<p>SHA-256 da cópia recebida:</p><code class="hash">${d.sha256}</code><p>Sem auditoria criptográfica das assinaturas.</p>`:''}</details><div class="doc-records">${d.recordIds.map(id=>{const rec=allRecords.find(x=>x.id===id);return rec?`<button data-case="${id}">${esc(rec.title)} →</button>`:''}).join('')}</div></article>`;}
function relatedDocuments(r){const docs=window.DOCUMENTS.filter(d=>d.recordIds.includes(r.id));return `<section class="related-documents"><h3>Documentos e processos</h3>${docs.length?docs.map(d=>`<div><a href="${esc(d.path)}" target="_blank" rel="noopener noreferrer">▤ ${esc(d.title)} ↗</a><p>${esc(d.kind)}${d.pages?' · '+d.pages+' páginas':''}. ${esc(d.limits)}</p>${d.guide.map(g=>`<a class="page-link" href="${esc(d.path)}#page=${g.page}" target="_blank" rel="noopener noreferrer">p. ${g.page} · ${esc(g.label)}</a>`).join('')}</div>`).join(''):'<p>Inteiro teor em PDF ainda não incorporado a esta ficha. As fontes abaixo documentam os marcos disponíveis; uma notícia institucional não substitui a íntegra dos autos.</p>'}</section>`;}
function caseDepth(r){return `${r.analysis?`<aside class="critical-analysis"><span class="overline">ANÁLISE EDITORIAL · OPINIÃO</span><h3>${esc(r.analysis.title)}</h3><p>${esc(r.analysis.text)}</p><small>Leitura crítica das fontes identificadas nesta ficha.</small></aside>`:''}${r.dossier?`<h3>Cronologia com fontes no dossiê</h3><ol class="case-timeline">${r.dossier.events.map(t=>`<li><strong>${formatDate(t.date)} · ${esc(t.title)}</strong><p>${esc(t.text)}</p></li>`).join('')}</ol>${permanentLink(r)}`:r.timeline?`<h3>Cronologia documentada</h3><ol class="case-timeline">${r.timeline.map(t=>`<li><strong>${esc(t.date)}</strong><p>${esc(t.text)}</p></li>`).join('')}</ol>`:''}${relatedDocuments(r)}`;}
function renderDocumentView(){const on=state.view==='documents';document.querySelectorAll('.metrics,.filters,.active-filters,.charts,.timeline-panel,.people-panel,.results').forEach(el=>el.hidden=on);$('document-library').hidden=!on;$('documents-nav').classList.toggle('active',on);$('documents-nav').setAttribute('aria-current',on?'page':'false');if(on)renderDocuments();}
function renderDocuments(){const library=$('document-library');if(library.childElementCount)return;library.innerHTML=`<div class="library-heading"><div><span class="overline">FONTES PRIMÁRIAS</span><h2>Da investigação ao julgamento</h2><p>${window.DOCUMENTS.filter(d=>d.pages).length} PDFs conferidos · ${window.DOCUMENTS.reduce((n,d)=>n+(d.pages||0),0).toLocaleString('pt-BR')} páginas · acesso adicional ao Senado. Há volumes parciais, identificados pelo alcance da cópia. Cada tipo de documento tem uma função diferente.</p></div></div><div class="doc-types" role="group" aria-label="Filtrar documentos"><button data-doc-type="" aria-pressed="true">Todos</button>${[...new Set(window.DOCUMENTS.map(d=>d.kind))].map(k=>`<button data-doc-type="${esc(k)}" aria-pressed="false">${esc(k)}</button>`).join('')}</div><label class="doc-search">Buscar nos títulos e descrições<input id="document-query" type="search" placeholder="Ex.: golpe, Câmara, CPI"></label><p id="document-count" aria-live="polite"></p><div class="document-grid" id="document-cards"></div>`;let type='';function draw(){const query=normalize($('document-query').value);const list=window.DOCUMENTS.filter(d=>(!type||d.kind===type)&&normalize([d.title,d.summary,d.issuer,d.process].join(' ')).includes(query));$('document-count').textContent=list.length+(list.length===1?' documento no recorte':' documentos no recorte');$('document-cards').innerHTML=list.map(documentCard).join('')||'<p>Nenhum documento encontrado. Limpe a busca ou selecione outro tipo.</p>'; }library.addEventListener('click',e=>{const b=e.target.closest('[data-doc-type]');if(!b)return;type=b.dataset.docType;library.querySelectorAll('[data-doc-type]').forEach(x=>x.setAttribute('aria-pressed',x===b));draw();});$('document-query').addEventListener('input',draw);draw();}
$('documents-nav').addEventListener('click',()=>setView('documents'));
$('documents-hero').addEventListener('click',()=>setView('documents'));

function renderFeatured(){const el=$('featured-dossiers');el.hidden=!['all','flavio'].includes(state.view);el.innerHTML='<div class="results-title"><h2>Dossiês em profundidade</h2><span>Revisão · 09/10/2026</span></div><div class="featured-grid">'+cases.filter(r=>r.dossier&&(state.view==='flavio'?r.people.includes('Flávio Bolsonaro'):['F01','J01','C01'].includes(r.id))).map(r=>`<a class="featured-card" href="${recordUrl(r)}"><span class="overline">${esc(r.status)}</span><h3>${esc(r.title)}</h3><p>${esc(r.dossier.lead)}</p><strong>Cronologia, documentos e responsabilidades ↗</strong></a>`).join('')+'</div>';}
function renderPeople(rows,unit){const counts=[...new Set(rows.flatMap(r=>r.people))].map(p=>[p,rows.filter(r=>r.people.includes(p)).length]).sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0])).slice(0,8);const max=Math.max(1,...counts.map(x=>x[1]));$('people-chart').innerHTML=counts.map(([p,n])=>`<button class="bar-row" data-speaker="${esc(p)}" aria-label="${esc(p)}: ${n} ${unit}. Filtrar" style="--bar:#A20301"><span class="bar-name">${esc(p)}</span><span class="bar-track"><span class="bar-fill" style="width:${n/max*100}%"></span></span><span class="bar-number">${n}</span></button>`).join('')||'<p>Sem pessoas neste recorte.</p>';}
